INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type) VALUES
('field3d_vg_a_value_surface_can_disagree_with_the_geometry_it_names', 'Three vg text surfaces made claims about geometry they did not read from (readout label, slider row, readout timing)', 'MAJOR', 'peter_parker:field3d_surgeon', '(a) VG_READOUT_LABEL.cross_mag was the hardcoded literal "|a x b|" while the cross sprite one namespace away already derived its name from flip_frac, so on the ORDER-MATTERS state the picture read b x a and the number beside it read |a x b|. (b) vgAnimValue resolves a knob as a pure function of state-local ms and never wrote the slider row, so a state ramping b_mag 2.00->2.50 left its own live row frozen at 2.00 with the thumb at t=0. (c) value_readouts rendered unconditionally, so Volume/Base/Height printed at t=0 -- 4.6 s before c appeared and 8.2 s before the solid was built; the same gate also fixed STATE_4, which printed a.(a x b) = 0.00 for 7.5 s before the arrow existed to be perpendicular to anything. All three were invisible to 475 headless assertions and to a 35/35 deterministic EYE pass, because in every case the NUMBER was correct.', 'A surface that NAMES or MEASURES a thing derives from the same value the thing is drawn from -- never a compile-time constant, never a value written once at state entry, never before the thing exists. SIBLING SURFACES OF ONE FIXED DEFECT ARE FIXED IN THE SAME PASS: when a defect is fixed on one surface, grep every other surface carrying the same claim in the same state before closing it.', 'js_eval', 'check:vector-geometry-3d sections 17/18/19 against the SHIPPED frame driver with a DOM registry: readout text at flip_frac 0/0.5/1 names the same arrow the sprite does; the row label at 7 sampled ms equals the value the geometry is built from with drag-seize preserved; no readout row is present in the panel HTML before its subject reveal fraction reaches 1.', 'FIXED', ARRAY['vector_products_in_space']::text[], ARRAY['src/lib/renderers/field_3d_renderer.ts', 'src/scripts/check_vector_geometry_3d.ts']::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('field3d_vg_overlay_relocation_moved_the_collision_instead_of_removing_it', 'An overlay moved out of one occupied corner into another occupied corner, because the destination was enumerated by hand', 'MAJOR', 'peter_parker:field3d_surgeon', '#vg_sliders was moved off #formula_overlay to bottom:12/left:12 to fix an earlier collision. The destination was enumerated by hand in a code comment (#vg_readout is top-anchored, #simPenBar is at top:10) and asserted exhaustive. #legend is fixed bottom:8/left:8 at the SAME z-index 10 with max-width 280, sharing 304px of width on the same bottom edge, and was never named -- so on both slider states a slider track struck through the state-label card. Recurrence of the OPEN scar call_site_enumeration_asserted_exhaustive_without_a_symbol_sweep, in layout.', 'A panel is placed against a PARSED set, never a remembered one, and a collision is REMOVED rather than relocated where a rule already says the other occupant does not belong (Rule 24: a scenario that labels its own objects suppresses the generic legend). Every position:fixed surface -- shell CSS and dynamically created panels alike -- must be classified by the gate, and an unclassified one fails.', 'js_eval', 'check:vector-geometry-3d section 21 parses every position:fixed rule from the emitted style block (with ${...} interpolations neutralised -- a naive brace match silently loses #legend) plus every dynamically created panel paired to its own id assignment; 174 classified today. Negative controls: an unsuppressed #legend is reported, the hand enumeration is re-run and shown to miss it, and a panel moved back to bottom-right is reported.', 'FIXED', ARRAY['vector_products_in_space']::text[], ARRAY['src/lib/renderers/field_3d_renderer.ts', 'src/scripts/check_vector_geometry_3d.ts']::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('field3d_vg_split_detaches_the_base_face_so_base_times_height_is_unreadable_as_one_solid', 'A decomposition threw the extracted base farther than the body is wide, reading as loss rather than as base x height', 'MODERATE', 'alex:json_author', 'The concept authored split_gap_k = 1, and the offset is k*(b+c) where |b+c| = 3.93 -- farther than |b| = 2.5 or |c| = 2.0, so the base travelled farther than the body is wide. Two of the three sub-claims in the visual report were REFUTED on measurement: the slide is exactly IN the base plane ((b+c).n_hat = 1.1e-16, deliberate -- an exploded lift along n would add the gap to the on-screen height while the readout prints h), and the silhouette shrink is CORRECT (the oblique solid becomes the right prism of the same base and height; that shrink IS the lesson). Only the gap was real.', 'A decomposition gap is measured as OVERLAP of the extracted piece against the body silhouette, not as centroid separation: 0.35 leaves 54 percent of the base still inside the solid while 0.6 leaves 20 percent. Note k = 1 is exactly the TANGENCY value, because the offset is k*(b+c) and |b+c| IS the base parallelogram own diagonal -- the knob has a natural geometric meaning and authored values should be read against it.', 'js_eval', 'Rasterise the extracted base against the projected prism silhouette at the authored camera; assert residual overlap between 10 and 30 percent and travel below the body widest edge.', 'FIXED', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('eye_capture_ms_pins_the_baseline_at_a_mid_state_hold_so_the_second_half_of_the_claim_is_unbaselined', 'A frozen pin landed on the zero beat, so the baseline archived the half of the state that was not its lesson', 'MAJOR', 'alex:json_author', 'STATE_3 teaches that the dot product is zero at 90 degrees AND NEGATIVE BEYOND IT, and authored eye_capture_ms 11500 against an animation end of 22400 -- so the frame that would be locked as the H2 baseline showed the zero and never the reversal. Fixed to 23000; the pin now archives theta = 130 and a.b = -3.86 (6 cos 130 = -3.857).', 'eye_capture_ms is derived from the animation end, never from the beat the author finds most photogenic. Where a state teaches a SEQUENCE of claims, the pin lands past the LAST of them.', 'js_eval', 'For every state, assert eye_capture_ms is greater than the last animate[] window end; report any pin that lands inside a hold that precedes a later beat.', 'FIXED', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('vg_s1_theta_label_renders_before_its_arc_and_holds_for_18s_without_it', 'A label appeared 18 seconds before the primitive it names', 'MODERATE', 'alex:json_author', 'STATE_1 drew the theta glyph alone on an otherwise empty canvas at t=0 and did not open its arc until 18400 ms of a 22 s state. Delaying the label was not authorable: the sprite gates on show_angle_arc only and fires at frame 0 regardless of arc_reveal_frac, so the ramp was dropped instead and the arc now rides the shared grow-in.', 'A label appears with the primitive it names. Where the renderer gates a label on a boolean rather than a reveal fraction, the fix is to remove the ramp, not to delay the label.', 'js_eval', 'For each state, assert no label primitive is visible at a time when its tracked object reveal fraction is 0.', 'FIXED', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('field3d_vg_slider_range_is_concept_wide_so_a_guided_state_cannot_bound_its_own_control', 'A guided state at a fixed camera inherited the sandbox slider range, so 47 percent of its control travel drove the picture off frame', 'CRITICAL', 'peter_parker:field3d_surgeon', 'vgSc reads config.slider_controls, which is CONCEPT-WIDE, and there was no per-state override. The cross-product-area state is camera_mode "authored" at a fixed R=16 and exposes b_mag, whose concept-wide range is 1.0-5.0 step 0.25 = 17 detents. Measured at the state OWN authored camera, FOV 60 / 16:9: 9 of 17 detents put the a x b tip OR ITS LABEL outside the frustum, on the state whose entire claim is that the arrow LENGTH IS THE AREA. The design was verified over the authored RAMP [2.0,2.5] and never over the live SLIDER range -- the worst-case law applied to a subset of what moves.', 'A control range is a CAMERA CLAIM. Every state exposing a live row at a fixed camera is swept over EVERY DETENT that row can reach, not over the authored ramp, and the sweep projects the LABEL as well as the object -- at 3.00 the label centre projects to NDC 1.0158 while the arrow tip is still on frame, so a tip-only sweep green-lights a clipped name. A guided state bounds its own row with vg.control_ranges, and the bound may never exclude the state own authored value or either end of its ramp (widen and PUBLISH instead of clamping silently).', 'js_eval', 'check:vector-geometry-3d section 20: enumerate every detent of the RESOLVED range and project the quad, the a x b tip AND the tip label quad through the shipped vgProjectPoint at the STATE own authored camera; assert zero off-frame. Negative controls: the concept-wide range leaves 9 of 17 off frame, and an auto_frame camera CANCELS the taught growth (screen arm ratio 1.0000 while the true length grows 1.25x).', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY['src/lib/renderers/field_3d_renderer.ts', 'src/scripts/check_vector_geometry_3d.ts']::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('eye_gate_skipped_for_an_unregistered_scenario_is_counted_as_a_pass', 'D5 was Skipped on all eight states and the EYE run still headlined 35/35 — and the registration fix did NOT take', 'MAJOR', 'peter_parker:field3d_surgeon', 'deriveMotionExpectations had no entry for vector_geometry_3d, so every state resolved to undefined and pixelGate emitted D5 as passed with evidence "Skipped -- motion expectation unknown"; visual_eyes aggregates those skips into the pass count, so a scenario with ZERO motion coverage reported a full deterministic pass (9 of the 35 were skips: 8x D5 plus H2). STATUS CORRECTED 2026-08-09: a vg entry WAS added and the SECOND EYE walk found D5 still skipped on all eight states, so the fix did not take. Unverified hypothesis from the walk: visual_eyes.ts:68 feeds deriveMotionExpectations(cached.physics_config) while the sibling reveal/hold derivations at :84-85 feed conceptJson ?? cached.physics_config, so the siblings resolve and this one does not.', 'A gate that is SKIPPED is not a gate that passed. Every new scenario_type registers in deriveMotionExpectations in the SAME change as its builder, and the registration is verified by an EYE run that shows D5 RUNNING -- not by the presence of the code. Separately, the EYE headline must report skips distinctly from passes; a run whose motion gate never executed cannot honestly read 35/35.', 'js_eval', 'After any visual:eyes run, count D5 lines whose evidence contains "Skipped"; refuse the summary if any state with a non-empty animate[] is among them.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY['src/lib/validators/visual/deriveStateMeta.ts', 'src/scripts/check_vector_geometry_3d.ts']::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('vg_flip_state_draws_two_equal_magnitudes_at_unequal_screen_lengths', 'The order-contrast state renders |a x b| and |b x a| — equal by definition — at 275 px and 182 px', 'MAJOR', 'alex:architect', 'STATE_6 teaches b x a = -(a x b): SAME LENGTH, opposite direction. At its authored pose (az 90 / el 30 / R 16) the +y arrow tip sits 13.94 units from the camera and the -y tip 20.06, so perspective renders them 275 px and 182 px -- a ratio of 0.662, the second arrow 34 percent shorter -- and the frozen baseline archives the short one. THE cross_mag LABEL FIX IS WHAT MADE THIS LEGIBLE: before it both readouts printed |a x b| so nobody would compare them; now one reads |b x a| = 6.50 beside a visibly shorter arrow. Fixing one truth-surface exposed the one beneath it.', 'A state whose taught claim is an EQUALITY of two magnitudes must be scored on the projected SCREEN length of both at the authored camera, not on their world lengths -- an angular-separation solve with a length floor has no term that can see this. Measured escape routes, neither free: R ~100+ or elevation ~2 degrees (the a-b plane is the xz-plane, so low elevation is edge-on). The third option is a design decision: accept the foreshortening and let the readout carry the claim, which is consistent with the standing invariant that every geometric claim carries a 3D-computed number.', 'js_eval', 'For any state asserting an equality of two drawn magnitudes, project both at the authored camera and assert their screen-length ratio is above 0.95.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('vg_camera_solve_frames_the_figure_at_one_sixth_of_canvas_width', 'A camera solve scored only on separation and a length floor leaves the drawn figure at 11-17 percent of frame width', 'MAJOR', 'peter_parker:field3d_surgeon', 'Every guided state places the origin at exact frame centre with all content growing right and down, so the left ~48 percent of the canvas is permanently empty and the drawn figure spans 11-17 percent of the 1280 px frame (S4 12 percent, S6 11 percent). The camera solve has terms for pairwise separation and a screen-length floor but NO FILL TERM, so a pose can be simultaneously correct and tiny. Not fixable without an authorable camera TARGET -- see the OPEN row field3d_scenario_renders_offcentre_because_camera_target_is_not_authorable.', 'A camera solve carries a bound on the drawn content bounding box as a fraction of frame AND on the empty margin, or every pose it certifies is also a small one.', 'js_eval', 'Project every rendered vertex at the authored camera; assert the content bbox spans at least a declared fraction of frame width and that no single margin exceeds a declared share.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('vg_state_1_hud_prints_magnitudes_before_either_vector_exists', 'A reveal-gate fixed on the state that reported it was not applied to the state one earlier', 'MODERATE', 'peter_parker:field3d_surgeon', 'The value_readouts reveal-gate shipped for STATE_7 and STATE_4, but STATE_1 still prints |a| = 3.00 and |b| = 2.00 at t=0 beside a lone theta glyph, before either vector is drawn.', 'When a gate is added to a readout set, it is applied to EVERY state readout set in the same dispatch -- a gate fixed on the state that reported it and skipped elsewhere ships the same defect one state earlier.', 'js_eval', 'Assert no readout row is present in the panel HTML at any ms before its subject reveal fraction reaches 1, across ALL states.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('vg_decomposition_pieces_lose_their_names_when_the_legend_is_suppressed', 'Suppressing the generic legend left the taught objects with no on-canvas label at all', 'MODERATE', 'ambiguous', 'The legend was removed for this scenario to end a corner collision (correct -- removing beats relocating). But STATE_7 base quad and height segment, and STATE_5 parallelogram -- whose entire claim is "this area is |a x b|" -- now carry no on-canvas label, and the only naming is a corner readout card.', 'Suppressing a legend is only safe when every element it named carries its own on-canvas label. Diff the legend key set against the labelled-element set BEFORE removing it.', 'js_eval', 'For a scenario suppressing the generic legend, assert every element the legend would have named has either its own label primitive or an authored sprite.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('vg_theta_readout_rounds_to_integer_degrees_while_its_product_uses_the_unrounded_angle', 'Two numbers on screen beside their own formula do not satisfy it at the displayed precision', 'MODERATE', 'ambiguous', 'theta prints as an integer while a.b is computed from the unrounded angle: STATE_2 t=8000 shows theta = 47 and a.b = 4.07, but 6 cos 47 = 4.09. STATE_3 t=17000 shows 100 and -1.03 against -1.04; t=20000 shows 121 and -3.12 against -3.09. A teacher checking the formula on screen finds it does not close.', 'Two numbers rendered beside their own formula must satisfy that formula AT THE DISPLAYED PRECISION -- either raise the angle precision or derive the product from the rounded value.', 'js_eval', 'For every state rendering a formula and its operands, recompute the formula from the DISPLAYED operand strings and assert it matches the displayed result.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('vg_projection_label_overprints_the_theta_arc_and_the_vertex', 'A label obstacle set covering text and panels does not cover strokes, so a label lands on the arc it measures against', 'MODERATE', 'peter_parker:field3d_surgeon', 'The |b| cos theta label renders directly on the theta arc stroke at the vertex in STATE_3 (t=17000, t=20000 and the FROZEN frame that would become the H2 baseline) and on the a x b shaft in STATE_8.', 'A label obstacle set includes the arc stroke and every shaft passing through the vertex, not only text and panels. A collision present on the frozen frame is a collision baked into the baseline.', 'js_eval', 'Project every label quad and assert zero intersection with any drawn stroke polyline at the pinned frame.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('visual_eyes_d7_passes_a_state_that_never_moved_at_all', 'The stuck-tail gate cannot fail a wholly static state, because its precondition is earlier motion', 'MODERATE', 'peter_parker:field3d_surgeon', 'STATE_8 is byte-identical across all 18 dense frames and 5 keyframes, and D7 passes it with the evidence "no frozen tail (last 3 pairs not all <0.1% AFTER EARLIER MOTION)" -- it passes because there was never any motion to die. Rule 37 requires the interaction_complete state to keep moving; whether a teacher drag animates it is not verifiable from frames either way.', 'A zero-motion series routes to a distinct verdict, never to the stuck-tail gate OK. A precondition of "after earlier motion" makes the wholly static case unfailable.', 'js_eval', 'If every adjacent frame pair in a state series is below the noise floor, emit a distinct STATIC verdict rather than passing D7.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('engine_bug_queue_filters_are_blind_to_subject_subdirectories', 'query_engine_bug_queue --field3d and --scenario cannot see concepts/mathematics/ or concepts/chemistry/', 'MODERATE', 'peter_parker:runtime_generation', 'loadConceptIndex in query_engine_bug_queue.ts does a NON-RECURSIVE readdirSync over src/data/concepts, so every subject-namespace concept is invisible to the derived fleet: --field3d omits this concept entirely and --scenario vector_geometry_3d hard-exits with "no concept declares scenario_type". The file own header already records a 2026-08-02 scar that a blind fleet list is a FALSE ALL-CLEAR; this is the same class reintroduced through a directory the derivation cannot walk. It is also the concrete mechanism behind the finding that a defect CLASS does not respect renderer boundaries: a row filed against a PCPL concept never surfaces for a field_3d dispatch.', 'Concept-index derivation walks subdirectories. And a subject- or renderer-FILTERED scar query is a claim about relevance: an engine dispatch queries its filter AND sweeps the table unfiltered for the CLASS it is about to build against.', 'js_eval', 'Assert loadConceptIndex returns every concept under src/data/concepts including subject subdirectories; assert --scenario resolves a scenario_type authored only by a subject-namespace concept.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('onframe_gate_projects_no_sprite_labels_and_uses_a_solver_pose_not_the_states_own', 'The on-frame gate would have green-lit a control range that clips the arrow own name', 'MAJOR', 'peter_parker:field3d_surgeon', 'check_vector_geometry_3d section 20 derives its camera from vgAutoFramePos rather than the state authored camera, and scores off-frame on the arrow tip and parallelogram vertices only -- it never projects the label. It therefore reports the widest on-frame detent as |b| = 3, while at the shipped state authored camera the label centre at 3.00 projects to NDC 1.0158 and the true answer is 2.75.', 'An on-frame gate projects EVERY RENDERED element including sprite labels, at the STATE own camera, never at a solver-derived one. A gate that measures a different camera from the one that ships is measuring a different sim.', 'js_eval', 'Assert section 20 resolves its pose via vgCamBaseFromState on the state block and includes label quads in the off-frame set.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('vg_explore_state_is_a_still_picture_for_its_entire_captured_life', 'The interaction_complete sandbox authors no continuous beat, so it is static until dragged', 'MODERATE', 'alex:json_author', 'All 18 dense frames and 5 keyframes of STATE_8 are byte-identical. Rule 37 requires the explore state to keep moving -- the player skips the freeze for interaction_complete precisely so the motion loops -- but this scenario authors no idle beat, so the sandbox is a still photograph until a teacher drags. Not verifiable from frames either way; flagged rather than passed.', 'An interaction_complete state authors a continuous idle beat (a slow turn, a looping phase) so Rule 37 free-run has something to run, and so the headless gate can see motion the teacher would see.', 'js_eval', 'Assert the explore state has either a non-empty animate[] or an idle sweep; assert its dense series is not byte-identical across all frames.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident'),
('skeleton_dod_declares_rendered_strings_the_shipped_engine_cannot_draw', 'A Definition of Done named three on-canvas strings with no renderer path, and carried stale derived numbers', 'MODERATE', 'alex:architect', 'The skeleton section 10b declares a b x c label, an "Area = 6.50" string inside the quad, and a direction +y/-y HUD token -- none of which the engine can render (there is exactly one cross arrow, vg_cross_vector = a x b, and no direction token exists in VG_READOUT_LABEL). Two of the three are undocumented as substitutions. Its Base 4.25 / Height 2.34 are also stale: the measured-correct values are 4.27 / 2.33, and the skeleton triple sits exactly on the 2-dp rounding boundary and cannot close.', 'Every string a Definition of Done declares is checked against a rendering path before the DoD is written, and every derived number is stated at the precision the sim will print, computed from the authored inputs -- never hand-rounded to a nicer value.', 'manual', 'Grep each DoD-declared on-canvas string against the renderer element and label token sets; recompute every derived DoD number from the authored inputs at display precision.', 'OPEN', ARRAY['vector_products_in_space']::text[], ARRAY[]::text[], 'session_2026-08-09_vector_products_gate_rounds', 'incident')
